package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.*;
import com.citacloud.springboot.contacloud.app.models.*;
import com.citacloud.springboot.contacloud.app.repositories.*;
import com.citacloud.springboot.contacloud.app.mappers.AgenteImpresionMapper;
import com.citacloud.springboot.contacloud.app.security.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.junit.jupiter.api.*;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
class PrintAgentAdminServiceTest {
 final UUID tenant=UUID.randomUUID(),empresa=UUID.randomUUID(),sucursal=UUID.randomUUID(),user=UUID.randomUUID(),id=UUID.randomUUID();
 final CashRegisterRepository cajas=mock(CashRegisterRepository.class);final AgenteImpresionRepository agents=mock(AgenteImpresionRepository.class);final VinculacionAgenteImpresionRepository pairings=mock(VinculacionAgenteImpresionRepository.class);final CredencialAgenteImpresionRepository credentials=mock(CredencialAgenteImpresionRepository.class);final SucursalRepository branches=mock(SucursalRepository.class);final PrintAgentNumberService numbers=mock(PrintAgentNumberService.class);final PrintAgentTokenService tokens=mock(PrintAgentTokenService.class);final AuditoriaService audit=mock(AuditoriaService.class);final JdbcTemplate jdbc=mock(JdbcTemplate.class);
 final PrintAgentAdminService service=new PrintAgentAdminService(cajas,agents,pairings,credentials,branches,new AgenteImpresionMapper(),numbers,tokens,audit,new PrintAgentAssignmentService(cajas,agents),jdbc,Duration.ofMinutes(10),Duration.ofMinutes(2));
 AgenteImpresion agent;
 @BeforeEach void setup() throws Exception {autenticar(true);agent=new AgenteImpresion(tenant,empresa,sucursal,"PA-1","Agente",user);var field=AgenteImpresion.class.getDeclaredField("id");field.setAccessible(true);field.set(agent,id);when(agents.bloquear(id,tenant,empresa)).thenReturn(Optional.of(agent));var branch=mock(Sucursal.class);when(branch.isActivo()).thenReturn(true);when(branch.getNombre()).thenReturn("Principal");when(branches.findByIdAndEmpresaId(sucursal,empresa)).thenReturn(Optional.of(branch));when(agents.saveAndFlush(any())).thenAnswer(i->{AgenteImpresion a=i.getArgument(0);var f=AgenteImpresion.class.getDeclaredField("id");f.setAccessible(true);if(a.getId()==null)f.set(a,id);return a;});when(numbers.siguiente(tenant,empresa)).thenReturn("PA-2");}
 @AfterEach void cleanup(){SecurityContextHolder.clearContext();}
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(ints={10,25,50,100}) void respetaElTamanoElegidoEnElPaginador(int tamano){when(agents.buscar(eq(tenant),eq(empresa),anyString(),nullable(EstadoAgenteImpresion.class),eq(true),anyCollection(),any(org.springframework.data.domain.Pageable.class))).thenReturn(org.springframework.data.domain.Page.empty());service.buscar("",null,0,tamano);var pagina=org.mockito.ArgumentCaptor.forClass(org.springframework.data.domain.Pageable.class);verify(agents).buscar(eq(tenant),eq(empresa),eq(""),isNull(),eq(true),anyCollection(),pagina.capture());assertThat(pagina.getValue().getPageSize()).isEqualTo(tamano);}
 @Test void crearPersisteVariasCajasYPreferenciaPropia(){UUID c1=UUID.randomUUID(),c2=UUID.randomUUID();caja(c1,sucursal);caja(c2,sucursal);var dto=service.crear(new CrearAgenteImpresionInput("Nuevo",sucursal,List.of(c1,c2),false));var saved=org.mockito.ArgumentCaptor.forClass(AgenteImpresion.class);verify(agents).saveAndFlush(saved.capture());assertThat(saved.getValue().getCajas()).hasSize(2);assertThat(saved.getValue().isMostrarPdfAlImprimir()).isFalse();assertThat(dto.mostrarPdfAlImprimir()).isFalse();}
 @Test void editarCajasNoRotaCredencialesNiGeneraCodigo(){UUID old=UUID.randomUUID(),added=UUID.randomUUID();agent.reemplazarCajas(Set.of(caja(old,sucursal)));caja(added,sucursal);agent.vincular("PC","1","Windows");service.editar(id,new EditarAgenteImpresionInput("Editado",sucursal,List.of(added),false,0));assertThat(agent.getCajas()).extracting(Caja::getId).containsExactly(added);assertThat(agent.isMostrarPdfAlImprimir()).isFalse();assertThat(agent.getEstado()).isEqualTo(EstadoAgenteImpresion.ACTIVE);verifyNoInteractions(credentials,pairings,tokens);verify(jdbc).update(contains("status='CANCELLED'"),any(Object[].class));}
 @Test void permisoDeEdicionNoPermiteCambiarPdfSinPermisoEspecifico(){autenticar(false);UUID caja=UUID.randomUUID();caja(caja,sucursal);assertThatThrownBy(()->service.editar(id,new EditarAgenteImpresionInput("Nombre",sucursal,List.of(caja),false,0))).isInstanceOf(AccessDeniedException.class);assertThat(agent.isMostrarPdfAlImprimir()).isTrue();verify(agents,never()).flush();}
 @Test void cambioDeSucursalEliminaPrimeroLasRelacionesAnteriores(){UUID old=UUID.randomUUID(),nuevo=UUID.randomUUID(),otra=UUID.randomUUID();agent.reemplazarCajas(Set.of(caja(old,sucursal)));caja(nuevo,otra);var branch=mock(Sucursal.class);when(branch.isActivo()).thenReturn(true);when(branch.getNombre()).thenReturn("Otra");when(branches.findByIdAndEmpresaId(otra,empresa)).thenReturn(Optional.of(branch));var contador=new java.util.concurrent.atomic.AtomicInteger();doAnswer(i->{if(contador.getAndIncrement()==0){assertThat(agent.getCajas()).isEmpty();assertThat(agent.getSucursalId()).isEqualTo(sucursal);}return null;}).when(agents).flush();service.editar(id,new EditarAgenteImpresionInput("Nombre",otra,List.of(nuevo),true,0));assertThat(agent.getSucursalId()).isEqualTo(otra);assertThat(agent.getCajas()).extracting(Caja::getId).containsExactly(nuevo);}
 @Test void noPermiteSobrescribirCambiosConcurrentes(){assertThatThrownBy(()->service.editar(id,new EditarAgenteImpresionInput("Nombre",sucursal,List.of(UUID.randomUUID()),true,9))).isInstanceOf(ReglaNegocioException.class).hasMessageContaining("El agente cambió");verifyNoInteractions(cajas,jdbc);}
 private void autenticar(boolean permisoPdf){var permisos=new HashSet<>(Set.of("agentes_impresion.ver","agentes_impresion.crear","agentes_impresion.editar"));if(permisoPdf)permisos.add("facturas.configurar_impresion");var p=new TenantPrincipal(user,tenant,empresa,null,"DEMO","Admin","admin","",true,true,Set.of(),permisos);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(p,null,p.getAuthorities()));}
 private Caja caja(UUID id,UUID branch){var c=mock(Caja.class);when(c.getId()).thenReturn(id);when(c.getNombre()).thenReturn("Caja "+id);when(c.getTenantId()).thenReturn(tenant);when(c.getEmpresaId()).thenReturn(empresa);when(c.getSucursalId()).thenReturn(branch);when(c.isActivo()).thenReturn(true);when(cajas.bloquearParaOperacion(id,tenant,empresa)).thenReturn(Optional.of(c));return c;}
}
